// Google Analytics 4 Report
// ⚠️ CẦN: Google Analytics API credentials (OAuth2 hoặc Service Account)
// API Docs: https://developers.google.com/analytics/devguides/reporting/data/v1

// Mock data - Thay thế bằng HTTP Request đến GA4 API thật
// HTTP Request config:
// Method: POST
// URL: https://analyticsdata.googleapis.com/v1beta/properties/YOUR_PROPERTY_ID:runReport
// Headers: Authorization: Bearer YOUR_ACCESS_TOKEN
// Body: {
//   "dateRanges": [{ "startDate": "yesterday", "endDate": "yesterday" }],
//   "metrics": [{ "name": "activeUsers" }, { "name": "screenPageViews" }, { "name": "bounceRate" }],
//   "dimensions": [{ "name": "date" }]
// }

const gaData = {
  visitors: 1250,
  page_views: 3420,
  bounce_rate: 42.5,
  avg_session_duration: 185, // seconds
  top_pages: [
    { path: '/trang-chu', views: 890 },
    { path: '/san-pham', views: 567 },
    { path: '/lien-he', views: 234 }
  ]
};

return [{
  json: {
    source: 'google_analytics',
    date: new Date().toISOString().split('T')[0],
    ...gaData,
    fetched_at: new Date().toISOString(),
    timezone: 'Asia/Ho_Chi_Minh'
  }
}];

// Social Media Metrics
// ⚠️ CẦN: API tokens cho từng platform

// Facebook Graph API: https://developers.facebook.com/docs/graph-api
// LinkedIn API: https://learn.microsoft.com/en-us/linkedin/
// Twitter API: https://developer.twitter.com/en/docs/twitter-api

const socialData = {
  facebook: {
    followers: 5230,
    posts: 3,
    likes: 456,
    shares: 89,
    comments: 67
  },
  linkedin: {
    followers: 2100,
    posts: 5,
    likes: 234,
    shares: 45,
    comments: 23
  },
  twitter: {
    followers: 1890,
    tweets: 8,
    likes: 123,
    retweets: 34,
    replies: 12
  }
};

// Calculate totals
const totalFollowers = socialData.facebook.followers + socialData.linkedin.followers + socialData.twitter.followers;
const totalEngagement = 
  socialData.facebook.likes + socialData.facebook.shares + socialData.facebook.comments +
  socialData.linkedin.likes + socialData.linkedin.shares + socialData.linkedin.comments +
  socialData.twitter.likes + socialData.twitter.retweets + socialData.twitter.replies;

return [{
  json: {
    source: 'social_media',
    date: new Date().toISOString().split('T')[0],
    ...socialData,
    total_followers: totalFollowers,
    total_engagement: totalEngagement,
    fetched_at: new Date().toISOString()
  }
}];

// Email Campaign Stats
// ⚠️ CẦN: SendGrid hoặc Mailchimp API key

// SendGrid API: https://docs.sendgrid.com/api-reference/
// Mailchimp API: https://mailchimp.com/developer/api/

const emailData = {
  sends: 2450,
  opens: 1230,
  clicks: 456,
  bounces: 12,
  unsubscribes: 5,
  spam_reports: 1,
  open_rate: 50.2,
  click_rate: 18.6,
  bounce_rate: 0.5,
  unsubscribe_rate: 0.2
};

return [{
  json: {
    source: 'email_campaign',
    date: new Date().toISOString().split('T')[0],
    ...emailData,
    fetched_at: new Date().toISOString()
  }
}];

// Aggregate all metrics into single report
const analytics = $('Fetch Google Analytics Data').first().json;
const social = $('Fetch Social Media Metrics').first().json;
const email = $('Fetch Email Campaign Stats').first().json;

const date = new Date().toLocaleDateString('vi-VN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Generate insights
const insights = [];

if (analytics.bounce_rate > 50) insights.push('⚠️ Bounce rate cao (>50%) - Cần cải thiện landing pages');
if (analytics.avg_session_duration < 60) insights.push('⚠️ Thời gian on-site thấp - Content chưa hấp dẫn');
if (email.open_rate < 20) insights.push('⚠️ Email open rate thấp - Cần cải thiện subject lines');
if (social.total_engagement < 100) insights.push('💡 Social engagement thấp - Tăng tần suất đăng bài');

if (insights.length === 0) insights.push('✅ Tất cả metrics trong ngưỡng tốt!');

const report = {
  date,
  date_short: new Date().toISOString().split('T')[0],
  website: {
    visitors: analytics.visitors,
    page_views: analytics.page_views,
    bounce_rate: `${analytics.bounce_rate}%`,
    avg_session: `${Math.floor(analytics.avg_session_duration / 60)}m ${analytics.avg_session_duration % 60}s`
  },
  social: {
    total_followers: social.total_followers,
    total_engagement: social.total_engagement,
    facebook: social.facebook,
    linkedin: social.linkedin,
    twitter: social.twitter
  },
  email: {
    sends: email.sends,
    open_rate: `${email.open_rate}%`,
    click_rate: `${email.click_rate}%`,
    unsubscribes: email.unsubscribes
  },
  insights,
  formatted: {
    email_body: `BÁO CÁO ANALYTICS HÀNG NGÀY
━━━━━━━━━━━━━━━━━━━━
📅 Ngày: ${date}

🌐 WEBSITE
━━━━━━━━━━━━━━━━━━━━
👥 Visitors: ${analytics.visitors.toLocaleString('vi-VN')}
📄 Page Views: ${analytics.page_views.toLocaleString('vi-VN')}
📊 Bounce Rate: ${analytics.bounce_rate}%
⏱️ Avg Session: ${Math.floor(analytics.avg_session_duration / 60)}m ${analytics.avg_session_duration % 60}s

📱 SOCIAL MEDIA
━━━━━━━━━━━━━━━━━━━━
👥 Total Followers: ${social.total_followers.toLocaleString('vi-VN')}
💬 Total Engagement: ${social.total_engagement.toLocaleString('vi-VN')}

📧 EMAIL CAMPAIGN
━━━━━━━━━━━━━━━━━━━━
📤 Sends: ${email.sends.toLocaleString('vi-VN')}
📬 Open Rate: ${email.open_rate}%
🖱️ Click Rate: ${email.click_rate}%
❌ Unsubscribes: ${email.unsubscribes}

💡 INSIGHTS
━━━━━━━━━━━━━━━━━━━━
${insights.join('\n')}

━━━━━━━━━━━━━━━━━━━━
Tự động tạo bởi n8n Workflow`,
    slack_body: `📊 *Daily Analytics Report - ${date}*

🌐 *Website*
👥 Visitors: ${analytics.visitors.toLocaleString('vi-VN')}
📄 Page Views: ${analytics.page_views.toLocaleString('vi-VN')}
📊 Bounce Rate: ${analytics.bounce_rate}%

📱 *Social Media*
👥 Followers: ${social.total_followers.toLocaleString('vi-VN')}
💬 Engagement: ${social.total_engagement.toLocaleString('vi-VN')}

📧 *Email*
📤 Sends: ${email.sends.toLocaleString('vi-VN')}
📬 Open Rate: ${email.open_rate}%
🖱️ Click Rate: ${email.click_rate}%

💡 *Insights*
${insights.join('\n')}`
  }
};

return [{ json: report }];
